            if (c == '-') {
                sgn = -1;
                c = readByte();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return res * sgn;
        }

        public long nextLong() {
            int c = readByte();
            while (c <= ' ' && c != -1) c = readByte();
            if (c == -1) return -1;
            long sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = readByte();
            }
            long res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return res * sgn;
        }
    }

    static class ValueIndex {
        long[] distinctVals;
        int[] head;
        int[] tail;
        int[] pos;

        public ValueIndex(long[] rawVals, int n) {
            long[] packed = new long[n];
            for (int i = 0; i < n; i++) {
                packed[i] = (rawVals[i] << 32) | (i + 1); // 1-based index
            }
            shuffle(packed);
            Arrays.sort(packed);

            int countDistinct = 0;
            for (int i = 0; i < n; i++) {
                if (i == 0 || (packed[i] >>> 32) != (packed[i - 1] >>> 32)) {
                    countDistinct++;
                }
            }

            distinctVals = new long[countDistinct];
            head = new int[countDistinct];
            tail = new int[countDistinct];
            pos = new int[n];

            int dIdx = -1;
            for (int i = 0; i < n; i++) {
                long val = packed[i] >>> 32;
                int p = (int) (packed[i] & 0xFFFFFFFFL);
                pos[i] = p;

                if (i == 0 || val != (packed[i - 1] >>> 32)) {
                    dIdx++;
                    distinctVals[dIdx] = val;
                    head[dIdx] = i;
                }
                tail[dIdx] = i;
            }
        }

        private static void shuffle(long[] arr) {
            Random rnd = new Random(42);
            for (int i = arr.length - 1; i > 0; i--) {
                int j = rnd.nextInt(i + 1);
                long tmp = arr[i];
                arr[i] = arr[j];
                arr[j] = tmp;
            }
        }

