            if (low > high) return 0;
            int idx = Arrays.binarySearch(distinctVals, val);
            if (idx < 0) return 0;

            int start = head[idx];
            int end = tail[idx];

            int l = lowerBound(pos, start, end, low);
            int r = upperBound(pos, start, end, high);
            return Math.max(0, r - l);
