        private int lowerBound(int[] arr, int start, int end, int target) {
            int l = start, r = end;
            int ans = end + 1;
            while (l <= r) {
                int mid = (l + r) >>> 1;
                if (arr[mid] >= target) {
                    ans = mid;
                    r = mid - 1;
                } else {
                    l = mid + 1;
                }
            }
            return ans;
        }

        private int upperBound(int[] arr, int start, int end, int target) {
            int l = start, r = end;
            int ans = end + 1;
            while (l <= r) {
                int mid = (l + r) >>> 1;
                if (arr[mid] > target) {
                    ans = mid;
                    r = mid - 1;
                } else {
                    l = mid + 1;
                }
            }
            return ans;
        }
    }

