        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public long nextLong() {
            int b = readByte();
            while (b <= ' ' && b != -1) b = readByte();
            if (b == -1) return -1;
            boolean neg = false;
            if (b == '-') {
                neg = true;
                b = readByte();
            }
            long res = 0;
            while (b >= '0' && b <= '9') {
                res = res * 10 + (b - '0');
                b = readByte();
            }
            return neg ? -res : res;
        }

        public int nextInt() {
            return (int) nextLong();
        }
    }

    static class Entry implements Comparable<Entry> {
        long val;
        int idx;

        Entry(long val, int idx) {
            this.val = val;
            this.idx = idx;
        }

        @Override
        public int compareTo(Entry o) {
            if (this.val != o.val) {
                return Long.compare(this.val, o.val);
            }
            return Integer.compare(this.idx, o.idx);
        }
    }

    static int lowerBound(Entry[] arr, long val, int idx) {
        int l = 0, r = arr.length;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (arr[m].val < val || (arr[m].val == val && arr[m].idx < idx)) {
                l = m + 1;
            } else {
                r = m;
            }
        }
        return l;
    }

    static int upperBound(Entry[] arr, long val, int idx) {
        int l = 0, r = arr.length;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (arr[m].val < val || (arr[m].val == val && arr[m].idx <= idx)) {
                l = m + 1;
            } else {
                r = m;
            }
        }
        return l;
    }

    static int countRange(Entry[] arr, long val, int low, int high) {
        if (low > high) return 0;
        return upperBound(arr, val, high) - lowerBound(arr, val, low);
    }

    public static void main(String[] args) {
