            A[i] = scanner.nextLong();
            X[i] = A[i] + i;
            Y[i] = i - A[i];
            entriesX[i - 1] = new Entry(X[i], i);
            entriesY[i - 1] = new Entry(Y[i], i);
        }

        Arrays.sort(entriesX);
        Arrays.sort(entriesY);

        int[] T = new int[N + 1];
        Arrays.fill(T, Q + 1);

