            int d = scanner.nextInt();
            T[d] = t;
        }

        long[] prio = new long[N + 1];
        for (int i = 1; i <= N; i++) {
            prio[i] = ((long) T[i] << 32) | i;
        }

        int[] L = new int[N + 1];
        int[] R = new int[N + 1];
        int[] stack = new int[N + 1];
        int top = 0;

        for (int i = 1; i <= N; i++) {
            while (top > 0 && prio[stack[top]] > prio[i]) {
                top--;
            }
            L[i] = (top == 0) ? 1 : stack[top] + 1;
            stack[++top] = i;
