            }
            R[i] = (top == 0) ? N : stack[top] - 1;
            stack[++top] = i;
        }

        long[] morrem = new long[Q + 2];

        for (int k = 1; k <= N; k++) {
            int leftLen = k - L[k];
            int rightLen = R[k] - k;
            long count = 0;

            if (leftLen <= rightLen) {
                for (int i = L[k]; i <= k; i++) {
                    int jMin = Math.max(k, i + 1);
                    long jMaxL = Math.min((long) R[k], i + K);
                    if (jMin <= jMaxL) {
                        int jMax = (int) jMaxL;
                        count += countRange(entriesX, X[i] + K, jMin, jMax);
                        count += countRange(entriesY, Y[i] + K, jMin, jMax);

                        if (i + K <= R[k] && i + K >= k) {
                            int j = (int) (i + K);
                            if (A[i] == A[j]) {
                                count--;
                            }
                        }
                    }
                }
            } else {
                for (int j = k; j <= R[k]; j++) {
                    long iMinL = Math.max((long) L[k], j - K);
                    int iMax = Math.min(k, j - 1);
                    if (iMinL <= iMax) {
                        int iMin = (int) iMinL;
                        count += countRange(entriesX, X[j] - K, iMin, iMax);
                        count += countRange(entriesY, Y[j] - K, iMin, iMax);

                        if (j - K >= L[k] && j - K <= k) {
                            int i = (int) (j - K);
                            if (A[i] == A[j]) {
                                count--;
                            }
                        }
                    }
                }
            }

